source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    one_id = [[-1] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1 and one_id[r][c] < 0:
                k = len(comps)
                q = [(r, c)]
                one_id[r][c] = k
                cells = []
                while q:
                    y, x = q.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and one_id[ny][nx] < 0:
                            one_id[ny][nx] = k
                            q.append((ny, nx))
                comps.append(cells)

    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr, nc))
    enclosed = [[grid[r][c] == 0 and not outside[r][c] for c in range(w)] for r in range(h)]

    active = set()
    for r in range(h):
        for c in range(w):
            if enclosed[r][c]:
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                        active.add(one_id[nr][nc])

    out = [row[:] for row in grid]
    if not active:
        return out
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            inside = enclosed[r][c]
            near = False
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1 and one_id[nr][nc] in active:
                        near = True
            if inside and near:
                out[r][c] = 3
            elif not inside and near:
                out[r][c] = 2
    return out
'''
